#include <vector>
#include <omp.h>

bool contains(std::vector<int> const& x, int target) {
    bool found = false;

    #pragma omp parallel for default(none) shared(x, target) reduction(||:found)
    for (int i = 0; i < static_cast<int>(x.size()); ++i) {
        found = found || (x[i] == target);
    }

    return found;
}
